/* GENERATED by gen_hcon_vault.py -- models are generated.
   source view : BJAZ_HM_PREAUTH_REQUEST   (run: opus_health_v2)
   target      : HUB_PARTY
   key slot    : HUB_PARTY_BK__INSURED_CARD_NO
   key origin  : map.resolved_key
   key tier    : tier1_business_code
   reject class: single_operand_guarded
   operands    : INSURED_CARD_NO
   KEY FORM: md5(upper('HUB_PARTY|' || <business key>)), emitted EXPLICITLY -- no macro computes a
   hash in this build. The namespace is a MEASURED collision guard: opus_health_v2 emits
   md5(upper(HUB_ASSESSMENT_BK__SCRUTINY_NO)) AND md5(upper(HUB_PROPOSAL_BK__SCRUTINY_NO)),
   the same column under two hubs, which collide without it; legacy namespaces 1822 of 1822.
   CRITICAL PRECISION: the namespace separates HUBS, NOT REGISTRIES WITHIN A HUB.
   'HUB_POLICY|' prefixes POLICY_REF and POLICY_NO identically, so it does nothing to keep
   two identifier populations inside one hub apart.
   DEGENERATE SENTINEL 'HEALTHCARD:': the WHERE below IS the declared reject predicate.
   A row failing it is diverted to the reject log, never silently dropped.
*/

select
    md5(upper('HUB_PARTY|' || (HUB_PARTY_BK__INSURED_CARD_NO))) as HUB_PARTY_HK
    , HUB_PARTY_BK__INSURED_CARD_NO as HUB_PARTY_BK__INSURED_CARD_NO
    , 'BJAZ_HM_PREAUTH_REQUEST' as RECORD_SOURCE
    , 'opus_health_v2' as SOURCE_RUN
    , current_timestamp() as LOAD_DATETIME
from {{ ref('stage_hm_preauth_request') }}
where (nullif('HEALTHCARD:' || nullif(trim(INSURED_CARD_NO),''), 'HEALTHCARD:')) is not null
  and (HUB_PARTY_BK__INSURED_CARD_NO) <> 'HEALTHCARD:'
